using Microsoft.AspNetCore.Mvc; using RaceDay.Mvc.Models; using RaceDay.Mvc.Services;
namespace RaceDay.Mvc.Controllers;
public class OrganiserController(RaceDayApiClient api):Controller {
 private bool Allowed()=>HttpContext.Session.GetString("UserRole")=="Organiser" && HttpContext.Session.GetInt32("UserId")!=null;
 private IActionResult Denied()=>RedirectToAction("Login","Account");
 public async Task<IActionResult> Index(){if(!Allowed())return Denied();var events=await api.Get<List<EventDto>>("api/events")??[]; var mine=events.Where(e=>e.OrganiserId==HttpContext.Session.GetInt32("UserId")).ToList(); ViewBag.Enrolments=0; foreach(var e in mine){var a=await api.Get<List<EnrollmentDto>>($"api/enrollments/events/{e.Id}");ViewBag.Enrolments+=(a?.Count??0);} return View(mine);}
 public async Task<IActionResult> Events(){if(!Allowed())return Denied();var events=await api.Get<List<EventDto>>("api/events")??[];return View(events.Where(e=>e.OrganiserId==HttpContext.Session.GetInt32("UserId")).ToList());}
 [HttpGet] public IActionResult Create()=>Allowed()?View(new EventVm()):Denied();
 [HttpPost][ValidateAntiForgeryToken] public async Task<IActionResult> Create(EventVm vm){if(!Allowed())return Denied();if(!ModelState.IsValid)return View(vm);try{var e=await api.Post<EventDto>("api/events",new{name=vm.Name,description=vm.Description,eventDate=vm.EventDate,location=vm.Location,distanceKm=vm.DistanceKm,eventType=vm.EventType});if(vm.Banner!=null&&e!=null)await api.Upload<object>($"api/events/{e.Id}/banner",vm.Banner);TempData["Success"]="Event created successfully.";return RedirectToAction(nameof(Events));}catch(ApiException ex){ModelState.AddModelError("",ex.Message);return View(vm);}}
 [HttpGet] public async Task<IActionResult> Edit(int id){if(!Allowed())return Denied();var e=await api.Get<EventDto>($"api/events/{id}");if(e==null||e.OrganiserId!=HttpContext.Session.GetInt32("UserId"))return NotFound();return View(new EventVm{Id=e.Id,Name=e.Name,Description=e.Description,EventDate=e.EventDate,Location=e.Location,DistanceKm=e.DistanceKm,EventType=e.EventType});}
 [HttpPost][ValidateAntiForgeryToken] public async Task<IActionResult> Edit(EventVm vm){if(!Allowed())return Denied();if(!ModelState.IsValid)return View(vm);try{await api.Put<EventDto>($"api/events/{vm.Id}",new{name=vm.Name,description=vm.Description,eventDate=vm.EventDate,location=vm.Location,distanceKm=vm.DistanceKm,eventType=vm.EventType});if(vm.Banner!=null)await api.Upload<object>($"api/events/{vm.Id}/banner",vm.Banner);TempData["Success"]="Event updated.";return RedirectToAction(nameof(Events));}catch(ApiException ex){ModelState.AddModelError("",ex.Message);return View(vm);}}
 [HttpPost][ValidateAntiForgeryToken] public async Task<IActionResult> Delete(int id){if(!Allowed())return Denied();try{await api.Delete($"api/events/{id}");TempData["Success"]="Event deleted.";}catch(ApiException e){TempData["Error"]=e.Message;}return RedirectToAction(nameof(Events));}
 public async Task<IActionResult> Categories(int id){if(!Allowed())return Denied();ViewBag.EventId=id;ViewBag.Event=await api.Get<EventDto>($"api/events/{id}");return View(await api.Get<List<CategoryDto>>($"api/events/{id}/categories")??[]);}
 [HttpPost][ValidateAntiForgeryToken] public async Task<IActionResult> AddCategory(CategoryVm vm){if(!Allowed())return Denied();try{await api.Post<CategoryDto>($"api/events/{vm.EventId}/categories",new{name=vm.Name,minimumAge=vm.MinimumAge,maximumAge=vm.MaximumAge,distanceKm=vm.DistanceKm});TempData["Success"]="Category added.";}catch(ApiException e){TempData["Error"]=e.Message;}return RedirectToAction(nameof(Categories),new{id=vm.EventId});}
 public async Task<IActionResult> Enrolments(int id){if(!Allowed())return Denied();ViewBag.Event=await api.Get<EventDto>($"api/events/{id}");return View(await api.Get<List<EnrollmentDto>>($"api/enrollments/events/{id}")??[]);}
 public async Task<IActionResult> Results(int id){if(!Allowed())return Denied();ViewBag.Event=await api.Get<EventDto>($"api/events/{id}");ViewBag.Enrolments=await api.Get<List<EnrollmentDto>>($"api/enrollments/events/{id}")??[];return View(await api.Get<List<ResultDto>>($"api/results/events/{id}")??[]);}
 [HttpPost][ValidateAntiForgeryToken] public async Task<IActionResult> RecordResult(ResultVm vm,int eventId){if(!Allowed())return Denied();try{await api.Post<ResultDto>("api/results",new{enrollmentId=vm.EnrollmentId,finishTime=vm.FinishTime,finishingPosition=vm.FinishingPosition});TempData["Success"]="Race result recorded.";}catch(ApiException e){TempData["Error"]=e.Message;}return RedirectToAction(nameof(Results),new{id=eventId});}
}
